package run.ikaros.finance; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException; @Service public class VoidTransactionService{private final FinanceTransactionRepository transactions;private final AccountRepository accounts;public VoidTransactionService(FinanceTransactionRepository t,AccountRepository a){transactions=t;accounts=a;}public Mono<TransactionView> voidTransaction(UUID actor,UUID id){return transactions.findById(id).filter(t->t.ownerId().equals(actor)).switchIfEmpty(Mono.error(new NotFoundException("Transaction 不存在或无权访问"))).flatMap(t->{if(t.status()!=TransactionStatus.POSTED)return Mono.error(new ConflictException("Transaction 已经不是 POSTED 状态"));return accounts.findById(t.accountId()).filter(a->a.ownerId().equals(actor)).switchIfEmpty(Mono.error(new NotFoundException("源 Account 不存在"))).flatMap(source->(t.type()==TransactionType.TRANSFER?accounts.findById(t.targetAccountId()).filter(a->a.ownerId().equals(actor)).switchIfEmpty(Mono.error(new NotFoundException("目标 Account 不存在"))).flatMap(target->reverse(source,target,t.amount())):reverse(source,null,t.amount(),t.type())).then(transactions.save(new FinanceTransactionEntity(t.id(),t.ledgerId(),t.ownerId(),t.type(),t.accountId(),t.targetAccountId(),t.amount(),t.currency(),t.categoryId(),t.payee(),t.note(),t.occurredAt(),TransactionStatus.VOIDED,t.source(),t.createdAt(),t.version()))));}).map(this::view);}private Mono<Void> reverse(AccountEntity source,AccountEntity target,BigDecimal amount){return save(source,source.currentBalance().add(amount)).then(save(target,target.currentBalance().subtract(amount)));}private Mono<Void> reverse(AccountEntity source,AccountEntity target,BigDecimal amount,TransactionType type){BigDecimal delta=type==TransactionType.INCOME?amount:type==TransactionType.EXPENSE?amount.negate():amount;return save(source,source.currentBalance().subtract(delta));}private Mono<Void> save(AccountEntity a,BigDecimal balance){return accounts.save(new AccountEntity(a.id(),a.ledgerId(),a.ownerId(),a.name(),a.type(),a.currency(),a.openingBalance(),balance,a.institution(),a.maskedIdentifier(),a.credentialRef(),a.archived(),a.createdAt(),a.updatedAt(),a.version())).then();}private TransactionView view(FinanceTransactionEntity x){return new TransactionView(x.id(),x.ledgerId(),x.type(),x.accountId(),x.targetAccountId(),x.amount(),x.currency(),x.categoryId(),x.payee(),x.note(),x.occurredAt(),x.status(),x.source());}}
